import { Bcgetuser } from "@/app/actions/bcuser";
import Swuserlist from "./swruserlist";
import Rnlist from "./swruserlist";

export default async function Userlist() {
  const res = await Bcgetuser();

  if (!res.success || !res.data) {
    return <p className="p-4 text-gray-500">No users found.</p>;
  }

  // 1. CRITICAL: Convert to plain JSON to strip hidden functions/methods
  // This prevents the "Functions are not valid as a child" error
  const cleanUsers = JSON.parse(JSON.stringify(res.data));

  return <Rnlist initialdata={res} />;
}
